// spec: specs/client-ordering.md §6
// client-ordering · кейс co-22 (.qa/tests/client-ordering/) — #157fed2c «קטלוג הלקוח: רשימת הקטגוריות לא מתעדכנת בלי רענון» (עבר QA 2026-10-14).
// Две роли одновременно, каждая в своём окне (asUser): admin переносит товар из категории A в B, buyer держит /shop открытым БЕЗ reload.
// Опустевшая A уходит из строки чипов и шторки «סינון ומיון» сразу при действии клиента (клик по чипу, «נקה הכל», «זמינות», «מיון»),
// не открывается в «0 מוצרים», и прежняя выдача «A · מוצר אחד» не показывается после закрытия шторки; снова наполненная A возвращается.
// Порог «сразу» — 3 с (фикс ~0.4 с; таймер 30 с — провал). Данные: категории «QA-AUTO-157f-<d|m><ts>-A/B» и товар «…-P»
// (отдельные на десктоп и iPhone — проекты идут параллельно). afterAll удаляет товар и обе категории.
import { test, expect } from '../../fixtures';
import type { Page, Browser } from '@playwright/test';
import * as path from 'path';
import * as H from '../inventory/_places';

test.describe.configure({ mode: 'serial' });

const auth = (role: string) => path.resolve(__dirname, `../../../auth/${role}.json`);
const TS = Date.now().toString().slice(-7);
const NOW = 3_000; // «сразу»: категории перечитываются до показа товаров (~0.4 с), не по 30-с таймеру
let A = '';
let B = '';
let P = '';
let productId = '';

// ---------- admin ----------
async function adminPage(browser: Browser) {
  const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  return { ctx, page: await ctx.newPage() };
}

async function openCategories(page: Page) {
  await page.goto('/catalog/categories');
  await expect(page.getByRole('heading', { level: 1, name: 'קטגוריות' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(/\d+ מוצרים|מוצר אחד/).first()).toBeVisible({ timeout: 20_000 }); // список загружен
}

async function createCategory(page: Page, name: string) {
  await page.getByRole('button', { name: 'קטגוריה חדשה' }).click();
  await page.getByRole('textbox', { name: /שם קטגוריה/ }).fill(name);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText(name, { exact: true }).first()).toBeVisible({ timeout: 15_000 });
}

async function deleteCategory(page: Page, name: string) {
  const label = page.getByText(name, { exact: true }).first();
  if (!(await label.count())) return;
  await label.locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]').getByRole('button', { name: 'פעולות' }).first().click();
  const item = page.getByRole('menuitem', { name: /^מחיקה/ });
  if (await item.isDisabled()) { await page.keyboard.press('Escape'); return; }
  await item.click();
  await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
  await expect(page.getByText(name, { exact: true })).toHaveCount(0, { timeout: 15_000 });
}

/** admin: товар P → категория name (форма редактирования). */
async function moveProduct(page: Page, name: string) {
  await page.goto(`/catalog/${productId}/edit`);
  const cb = page.getByRole('combobox', { name: 'קטגוריה' });
  await expect(cb.locator('option', { hasText: name })).toHaveCount(1, { timeout: 20_000 });
  await cb.selectOption((await cb.locator('option', { hasText: name }).getAttribute('value'))!);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page).toHaveURL(/\/catalog$/, { timeout: 20_000 });
}

// ---------- buyer ----------
const chip = (bp: Page, name: string) => bp.getByRole('button', { name, exact: true });
const heading = (bp: Page, text: string) => bp.locator('p').filter({ hasText: new RegExp(`^${text}$`) });

async function openShopInA(bp: Page) {
  await bp.goto('/shop');
  await expect(bp.getByRole('searchbox', { name: 'חיפוש מוצר' })).toBeVisible({ timeout: 30_000 });
  await expect(chip(bp, A)).toBeVisible({ timeout: 20_000 });
  await chip(bp, A).click();
  await expect(chip(bp, A)).toHaveAttribute('aria-pressed', 'true');
  await expect(heading(bp, A)).toBeVisible();
  await expect(bp.getByText('מוצר אחד', { exact: true })).toBeVisible({ timeout: 15_000 });
  await expect(bp.locator('article').filter({ hasText: P })).toHaveCount(1);
}

async function openSheet(bp: Page) {
  await bp.getByRole('button', { name: /^סינון ומיון/ }).click();
  const sheet = bp.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  await expect(sheet).toBeVisible();
  return sheet;
}

/** Закрыть шторку кнопкой «הצגת N מוצרים» / «הצגת מוצר אחד». */
async function applySheet(bp: Page) {
  const sheet = bp.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  const show = sheet.getByRole('button', { name: /^הצגת (\d+ מוצרים|מוצר אחד)$/ });
  await expect(show).toBeEnabled({ timeout: NOW });
  await show.click();
  await expect(sheet).toHaveCount(0);
}

/** С этого момента отмечать, если при закрытой шторке заголовок снова/ещё «A» + «מוצר אחד» (прежняя выдача). */
async function watchStale(bp: Page) {
  await bp.evaluate((a) => {
    const w = window as unknown as { __qaStale: string[] };
    w.__qaStale = [];
    const check = () => {
      if (document.querySelector('[role="dialog"]')) return;
      const ps = [...document.querySelectorAll('p')].map((p) => (p.textContent ?? '').trim());
      if (ps.includes(a) && ps.includes('מוצר אחד')) w.__qaStale.push(`${Math.round(performance.now())}ms`);
    };
    new MutationObserver(check).observe(document.body, { subtree: true, childList: true, characterData: true });
  }, A);
}
const staleSeen = (bp: Page) => bp.evaluate(() => (window as unknown as { __qaStale: string[] }).__qaStale);

/** Итог: A нет в строке, выбран «הכל», заголовок «כל המוצרים», нет «0 מוצרים» / «לא נמצאו מוצרים תואמים». */
async function expectAGoneAll(bp: Page) {
  await expect(chip(bp, A)).toHaveCount(0, { timeout: NOW });
  await expect(chip(bp, 'הכל')).toHaveAttribute('aria-pressed', 'true', { timeout: NOW });
  await expect(heading(bp, 'כל המוצרים')).toBeVisible({ timeout: NOW });
  await expect(bp.getByText('0 מוצרים', { exact: true })).toHaveCount(0);
  await expect(bp.getByText(/לא נמצאו מוצרים תואמים/)).toHaveCount(0);
  await expect(chip(bp, B)).toBeVisible({ timeout: NOW }); // список обновлён: B теперь с товаром
}

for (const tag of ['@desktop', '@iphone'] as const) {
  test.describe(`client-ordering — רשימת הקטגוריות מתעדכנת בלי רענון (#157fed2c) ${tag}`, () => {
    test.beforeAll(async ({ browser }, info) => {
      if (!info.project.name.match(tag === '@desktop' ? /^tests$/ : /^iphone$/)) return;
      test.setTimeout(240_000);
      const s = `${tag === '@desktop' ? 'd' : 'm'}${TS}`;
      A = `QA-AUTO-157f-${s}-A`;
      B = `QA-AUTO-157f-${s}-B`;
      P = `QA-AUTO-157f-${s}-P`;
      const { ctx, page } = await adminPage(browser);
      try {
        await openCategories(page);
        await createCategory(page, A);
        await createCategory(page, B);
        await H.createProduct(page, P, `QA157F${s.toUpperCase()}`, new Set());
        productId = await H.productId(page, P);
        await moveProduct(page, A);
      } finally {
        await ctx.close();
      }
    });

    test.afterAll(async ({ browser }, info) => {
      if (!info.project.name.match(tag === '@desktop' ? /^tests$/ : /^iphone$/) || !P) return;
      test.setTimeout(180_000);
      const { ctx, page } = await adminPage(browser);
      try {
        await H.findProduct(page, P);
        if (await H.qtyBtn(page, P).count()) {
          await (await H.openRowMenuDelete(page, P)).click();
          const dlg = page.getByRole('dialog');
          await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
          await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
          await expect(page.getByText(/נמחק\.|הוסר מהקטלוג/).first()).toBeVisible({ timeout: 15_000 });
        }
        await openCategories(page);
        for (const c of [A, B]) await deleteCategory(page, c);
      } finally {
        await ctx.close();
      }
    });

    test(`לחיצה על שבב של קטגוריה שהתרוקנה: השבב יוצא מהשורה, «הכל», בלי «0 מוצרים» — בלי רענון #157fed2c ${tag} @data`, async ({ asUser }) => {
      test.setTimeout(150_000);
      test.skip(!productId, 'данные не подготовлены');
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const buyer = await asUser('buyer');
      await moveProduct(admin, A);
      await openShopInA(buyer);
      await chip(buyer, 'הכל').click();
      await expect(chip(buyer, 'הכל')).toHaveAttribute('aria-pressed', 'true');

      await moveProduct(admin, B);
      // клиент не перезагружает страницу: снова нажимает A (если чип ещё виден)
      if (await chip(buyer, A).isVisible()) await chip(buyer, A).click({ timeout: 2_000 }).catch(() => {});
      await expectAGoneAll(buyer);
      await expect(heading(buyer, A)).toHaveCount(0);
    });

    test(`«נקה הכל» בתוך קטגוריה שהתרוקנה: היא יוצאת מהשורה ומהשכבה מיד #157fed2c ${tag} @data`, async ({ asUser }) => {
      test.setTimeout(150_000);
      test.skip(!productId, 'данные не подготовлены');
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const buyer = await asUser('buyer');
      await moveProduct(admin, A);
      await openShopInA(buyer);
      let sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'שם: א׳–ת׳' }).click();
      await applySheet(buyer);
      await expect(chip(buyer, A)).toHaveAttribute('aria-pressed', 'true');

      await moveProduct(admin, B);
      sheet = await openSheet(buyer);
      await sheet.getByRole('button', { name: 'נקה הכל' }).click();
      await expect(sheet.getByRole('radio', { name: A, exact: true })).toHaveCount(0, { timeout: NOW });
      await expect(sheet.getByRole('radio', { name: 'כל הקטגוריות' })).toBeChecked();
      await expect(sheet.getByRole('radio', { name: B, exact: true })).toBeVisible({ timeout: NOW });
      await watchStale(buyer);
      await applySheet(buyer);
      await expectAGoneAll(buyer);
      expect(await staleSeen(buyer), 'прежняя выдача «A · מוצר אחד» после закрытия шторки').toEqual([]);
    });

    test(`שינוי «זמינות» בתוך קטגוריה שהתרוקנה: בלי תוצאה שמורה («A · מוצר אחד»), הקטגוריה יוצאת, «הכל» #157fed2c ${tag} @data`, async ({ asUser }) => {
      test.setTimeout(150_000);
      test.skip(!productId, 'данные не подготовлены');
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const buyer = await asUser('buyer');
      await moveProduct(admin, A);
      await openShopInA(buyer);

      await moveProduct(admin, B);
      const sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'במלאי בלבד' }).click();
      await expect(sheet.getByRole('radio', { name: A, exact: true })).toHaveCount(0, { timeout: NOW });
      await watchStale(buyer);
      await applySheet(buyer);
      await expect(chip(buyer, A)).toHaveCount(0, { timeout: NOW });
      await expect(chip(buyer, 'הכל')).toHaveAttribute('aria-pressed', 'true');
      await expect(heading(buyer, A)).toHaveCount(0);
      await expect(buyer.locator('article').filter({ hasText: P })).toHaveCount(0); // P «אזל» — не в «במלאי בלבד»
      expect(await staleSeen(buyer), 'прежняя выдача «A · מוצר אחד» после закрытия шторки').toEqual([]);
    });

    test(`שינוי מיון בתוך קטגוריה שהתרוקנה — בלי תוצאה שמורה; אחרי שהמוצר חזר — הקטגוריה חוזרת ונפתחת עם המוצר בלי רענון #157fed2c ${tag} @data`, async ({ asUser }) => {
      test.setTimeout(180_000);
      test.skip(!productId, 'данные не подготовлены');
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const buyer = await asUser('buyer');
      await moveProduct(admin, A);
      await openShopInA(buyer);
      // сохранённые выдачи A для двух сортировок
      let sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'שם: א׳–ת׳' }).click();
      await applySheet(buyer);
      await expect(buyer.getByText('מוצר אחד', { exact: true })).toBeVisible({ timeout: 15_000 });
      sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'מומלץ' }).click();
      await applySheet(buyer);
      await expect(buyer.getByText('מוצר אחד', { exact: true })).toBeVisible({ timeout: 15_000 });

      await moveProduct(admin, B);
      sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'שם: א׳–ת׳' }).click();
      await expect(sheet.getByRole('radio', { name: A, exact: true })).toHaveCount(0, { timeout: NOW });
      await watchStale(buyer);
      await applySheet(buyer);
      await expectAGoneAll(buyer);
      expect(await staleSeen(buyer), 'прежняя выдача «A · מוצר אחד» после закрытия шторки').toEqual([]);

      // товар вернулся в A → смена сортировки возвращает A; клик по A — сразу товар, без «0 מוצרים»
      await moveProduct(admin, A);
      sheet = await openSheet(buyer);
      await sheet.getByRole('radio', { name: 'מחיר: מהזול ליקר' }).click();
      await expect(sheet.getByRole('radio', { name: A, exact: true })).toBeVisible({ timeout: NOW });
      await applySheet(buyer);
      await expect(chip(buyer, A)).toBeVisible({ timeout: NOW });
      await chip(buyer, A).click();
      await expect(heading(buyer, A)).toBeVisible({ timeout: NOW });
      await expect(buyer.getByText('מוצר אחד', { exact: true })).toBeVisible({ timeout: NOW });
      await expect(buyer.locator('article').filter({ hasText: P })).toHaveCount(1);
      await expect(buyer.getByText('0 מוצרים', { exact: true })).toHaveCount(0);
    });
  });
}
